"""GCU400 specialization of ``aten::cudnn_affine_grid_generator``.

Two backend facts shape this kernel:

* The shared implementation writes an interleaved ``(x, y)`` pair through a
  single ``tl.reshape(tl.join(...))`` store.  On GCU that masked interleaved
  store shifts the values as soon as ``BLOCK_W != W``, so every non power-of-two
  width came out garbage (max relative error ~4.4).  The masked path here
  therefore stores the two coordinate planes separately with their own stride,
  which stays exact for masked widths; only the unmasked, contiguous case uses
  one interleaved store of the whole ``(w, 2)`` row.
* GCU has no FP64 unit: a float64 ``theta`` cannot be legalized by the compiler,
  so the float64 path runs the same float32 kernels on a float32 workspace and
  casts the finished grid back into the float64 output buffer.  The grid dtype
  contract is preserved while the values carry float32 intermediate precision.

The grid is (row chunks * column blocks, N) and one program writes ``ROWS`` grid
rows for one batch element, which amortizes the six ``theta`` scalar loads that
the row-per-program layout pays for every row of every batch element.

Three write paths are used, in decreasing order of preference:

* ``_vec_flat_kernel`` -- one ``(w, 2)`` grid row is 2 * W consecutive elements,
  so for a power-of-two W the row pattern repeats inside every power-of-two
  block.  The per-lane ``norm_x`` / ``norm_y`` and the x-or-y coefficient
  selection are therefore hoisted out of the chunk loop, and a chunk costs one
  FMA plus one store per element.  Measured on GCU400 at 16x256x256 (2M
  elements): 8.1us fp16 / 11.5us fp32, against 39.5us / 43.3us for the plain
  flat kernel and 7.1us for a pure store of the same buffer.
* ``cudnn_affine_grid_generator_flat_kernel`` -- interleaved writer for
  power-of-two widths that are not contiguous or are too wide for the
  vectorized block.
* ``cudnn_affine_grid_generator_kernel`` -- masked fallback (odd W, odd H,
  strided ``out``).
"""

import logging

import torch
import triton
import triton.language as tl

from flag_gems.runtime import torch_device_fn
from flag_gems.utils import libentry
from flag_gems.utils import triton_lang_extension as tle

logger = logging.getLogger(__name__)

# Widest column block; wider grid rows are split over column blocks.
MAX_BLOCK_W = 1024
# Grid rows written by one program.  A sweep over 16x16 .. 256x256 on GCU400 put
# the knee at H/8, capped here so a single program never monopolizes a core.
MAX_ROWS = 16
# Hardware limit of grid.y (see triton_gcu backend OutOfResources check).
MAX_GRID_Y = 255
# Flat kernel tile: elements (not samples) written by one loop iteration, and
# the number of iterations per program.  16 x 2048 elements per program measured
# fastest on GCU400 (a sweep from 2048 to 131072 elements per program: 1024
# programs of 2048 elements cost 145us at 16x256x256, 64 programs of 32768
# elements cost 39.6us, and 32768 elements per program is also within 10% of the
# optimum for the fp32 grids).
FLAT_BLOCK = 2048
FLAT_CHUNKS = 16

# Vectorized flat kernel tuning (measured on GCU400, 16x16 .. 256x256 grids).
# Widest block: 8192 elements; a program keeps about sixteen chunks of it.
VEC_BLOCK_MIN = 1024
VEC_BLOCK_MAX = 8192
VEC_CHUNKS_PER_PROGRAM = 16
# Elements per program: 2-byte grids want 128K, 4-byte grids want 256K, which
# is what saturates the store path for the 16x256x256 shape.
VEC_ELEMENTS_2B = 131072
VEC_ELEMENTS_4B = 262144
# Below this much work per program the incremental ("accumulate") form of the
# chunk update measured faster than re-evaluating ``row_step * chunk``.
VEC_ACCUM_LIMIT = 65536


@libentry()
@triton.jit
def _vec_flat_kernel(
    grid_ptr,
    theta_ptr,
    W,
    HW2,
    LOG_HW2,
    STEP_X,
    STEP_Y,
    ROW_STEP,
    BLOCK: tl.constexpr,
    CHUNKS: tl.constexpr,
    PLANES: tl.constexpr,
    LOG_2W: tl.constexpr,
    ACCUM: tl.constexpr,
):
    """Write contiguous power-of-two blocks of the flat ``(n, h, w, 2)`` grid.

    ``BLOCK`` is a multiple of one grid row (2 * W elements), so lane l always
    belongs to the same column ``w`` and the same row offset inside the block.
    That makes ``norm_x`` and the x/y coefficient selection loop-invariant: a
    chunk only advances the row coordinate by ``BLOCK // (2 * W)`` rows, i.e. by
    the scalar ``row_step``, so each element of a chunk costs one FMA and one
    store.

    ``PLANES`` > 1 emits that many whole batch elements per program (the batch
    axis is folded in statically to keep the program count low for grids that
    are large in bytes); ``PLANES`` == 1 decodes the batch element and the row
    start from the flat program offset, which also covers a single plane being
    split over several programs.
    """
    pid = tle.program_id(0)
    # cudnn's align_corners=True normalization: coord = 2 * i / (size - 1) - 1,
    # with the denominator clamped to 1 so a size-1 axis collapses to -1.  The
    # steps and the row advance are computed on the host: for a size-1 axis the
    # in-kernel form folds to a Python integer and loses the tensor ``.to``.
    lane = tl.arange(0, BLOCK)
    # Element j of the flat grid is the x coordinate of sample j // 2 when j is
    # even and the y coordinate of the same sample when j is odd.
    is_y = (lane & 1) == 1
    col = (lane >> 1) & (W - 1)
    norm_x = col.to(tl.float32) * STEP_X - 1.0
    row_in_block = lane >> LOG_2W
    norm_y_base = row_in_block.to(tl.float32) * STEP_Y - 1.0
    out_dtype = grid_ptr.dtype.element_ty

    if PLANES == 1:
        flat_start = pid * (BLOCK * CHUNKS)
        n = flat_start >> LOG_HW2
        h_start = (flat_start & (HW2 - 1)) >> LOG_2W
        theta_base = n * 6
        coef_a = tl.where(
            is_y,
            tl.load(theta_ptr + theta_base + 3).to(tl.float32),
            tl.load(theta_ptr + theta_base + 0).to(tl.float32),
        )
        coef_b = tl.where(
            is_y,
            tl.load(theta_ptr + theta_base + 4).to(tl.float32),
            tl.load(theta_ptr + theta_base + 1).to(tl.float32),
        )
        coef_c = tl.where(
            is_y,
            tl.load(theta_ptr + theta_base + 5).to(tl.float32),
            tl.load(theta_ptr + theta_base + 2).to(tl.float32),
        )
        norm_y = norm_y_base + h_start.to(tl.float32) * STEP_Y
        base = coef_a * norm_x + coef_b * norm_y + coef_c
        ptr = grid_ptr + flat_start
        if ACCUM:
            step_vec = coef_b * ROW_STEP
            for chunk in tl.static_range(CHUNKS):
                tl.store(ptr + chunk * BLOCK + lane, base.to(out_dtype))
                base += step_vec
        else:
            for chunk in tl.static_range(CHUNKS):
                tl.store(
                    ptr + chunk * BLOCK + lane,
                    (base + coef_b * (ROW_STEP * chunk)).to(out_dtype),
                )
    else:
        ptr = grid_ptr + pid * PLANES * HW2
        for plane in tl.static_range(PLANES):
            theta_base = (pid * PLANES + plane) * 6
            coef_a = tl.where(
                is_y,
                tl.load(theta_ptr + theta_base + 3).to(tl.float32),
                tl.load(theta_ptr + theta_base + 0).to(tl.float32),
            )
            coef_b = tl.where(
                is_y,
                tl.load(theta_ptr + theta_base + 4).to(tl.float32),
                tl.load(theta_ptr + theta_base + 1).to(tl.float32),
            )
            coef_c = tl.where(
                is_y,
                tl.load(theta_ptr + theta_base + 5).to(tl.float32),
                tl.load(theta_ptr + theta_base + 2).to(tl.float32),
            )
            base = coef_a * norm_x + coef_b * norm_y_base + coef_c
            plane_ptr = ptr + plane * HW2
            if ACCUM:
                step_vec = coef_b * ROW_STEP
                for chunk in tl.static_range(CHUNKS):
                    tl.store(plane_ptr + chunk * BLOCK + lane, base.to(out_dtype))
                    base += step_vec
            else:
                for chunk in tl.static_range(CHUNKS):
                    tl.store(
                        plane_ptr + chunk * BLOCK + lane,
                        (base + coef_b * (ROW_STEP * chunk)).to(out_dtype),
                    )


@libentry()
@triton.jit
def cudnn_affine_grid_generator_kernel(
    grid_ptr,
    theta_ptr,
    H,
    W,
    out_s0,
    out_s1,
    out_s2,
    out_s3,
    NUM_COL_BLOCKS,
    NUM_ROW_CHUNKS,
    STEP_X,
    STEP_Y,
    BLOCK_W: tl.constexpr,
    ROWS: tl.constexpr,
    MASKED_W: tl.constexpr,
    MASKED_H: tl.constexpr,
    BATCH_ON_Y: tl.constexpr,
):
    """Write ``ROWS`` rows of ``BLOCK_W`` columns of one (n, h, w, 2) grid.

    ``BATCH_ON_Y`` selects how the linear program id is decoded: with the batch
    element on grid.y (N <= 255) the chunk index needs no division by N, and the
    flat form is used only for oversized batches.
    """
    pid = tle.program_id(0)
    if BATCH_ON_Y:
        n = tle.program_id(1)
        rem = pid
    else:
        n = pid // (NUM_COL_BLOCKS * NUM_ROW_CHUNKS)
        rem = pid % (NUM_COL_BLOCKS * NUM_ROW_CHUNKS)

    row_chunk = rem // NUM_COL_BLOCKS
    col_block = rem % NUM_COL_BLOCKS
    h_start = row_chunk * ROWS

    # theta[n] is a contiguous 2x3 affine matrix, so a fixed offset suffices.
    theta_base = n * 6
    theta_00 = tl.load(theta_ptr + theta_base + 0)
    theta_01 = tl.load(theta_ptr + theta_base + 1)
    theta_02 = tl.load(theta_ptr + theta_base + 2)
    theta_10 = tl.load(theta_ptr + theta_base + 3)
    theta_11 = tl.load(theta_ptr + theta_base + 4)
    theta_12 = tl.load(theta_ptr + theta_base + 5)

    # cudnn's align_corners=True normalization: coord = 2 * i / (size - 1) - 1.
    # Clamping the denominator to 1 makes the degenerate size-1 axis collapse to
    # -1 (its only sample sits at index 0); the steps come from the host because
    # a size-1 axis folds the in-kernel form to a Python integer.
    lane = tl.arange(0, BLOCK_W)
    col = col_block * BLOCK_W + lane
    norm_x = col.to(tl.float32) * STEP_X - 1.0

    # float16 is promoted to float32 like cuDNN does; the product terms that do
    # not depend on the row are hoisted out of the row loop.
    out_dtype = grid_ptr.dtype.element_ty
    acc_x = theta_00.to(tl.float32) * norm_x + theta_02.to(tl.float32)
    acc_y = theta_10.to(tl.float32) * norm_x + theta_12.to(tl.float32)
    theta_01 = theta_01.to(tl.float32)
    theta_11 = theta_11.to(tl.float32)

    row_base = n * out_s0 + col_block * BLOCK_W * out_s2
    grid_x_offsets = row_base + lane * out_s2
    for r in tl.static_range(ROWS):
        h = h_start + r
        norm_y = h.to(tl.float32) * STEP_Y - 1.0
        grid_x = (acc_x + theta_01 * norm_y).to(out_dtype)
        grid_y = (acc_y + theta_11 * norm_y).to(out_dtype)
        offsets = grid_x_offsets + h * out_s1
        if MASKED_W or MASKED_H:
            mask = lane < W - col_block * BLOCK_W
            if MASKED_H:
                mask = mask & (h < H)
            tl.store(grid_ptr + offsets, grid_x, mask=mask)
            tl.store(grid_ptr + offsets + out_s3, grid_y, mask=mask)
        else:
            tl.store(grid_ptr + offsets, grid_x)
            tl.store(grid_ptr + offsets + out_s3, grid_y)


@libentry()
@triton.jit
def cudnn_affine_grid_generator_flat_kernel(
    grid_ptr,
    theta_ptr,
    H,
    W,
    HW2,
    STEP_X,
    STEP_Y,
    LOG_W: tl.constexpr,
    BLOCK: tl.constexpr,
    CHUNKS: tl.constexpr,
    MASK: tl.constexpr,
    BATCH_ON_Y: tl.constexpr,
    NUM_CHUNKS: tl.constexpr,
):
    """Write contiguous chunks of the flat ``(n, h * w * 2)`` grid.

    The interleaved layout leaves only two choices on GCU: a strided 2-byte (or
    4-byte) store per plane, or an explicit interleave/reshape, and the
    interleave path costs ~8x more than the traffic itself.  Here each lane
    instead picks the x or the y formula by its parity, so the pair never has to
    be moved inside the program and every store is a plain contiguous store.
    ``W`` must be a power of two, which lets the ``h``/``w`` split use a shift.
    """
    pid = tle.program_id(0)
    if BATCH_ON_Y:
        n = tle.program_id(1)
    else:
        n = pid // NUM_CHUNKS
        pid = pid % NUM_CHUNKS

    theta_base = n * 6
    theta_00 = tl.load(theta_ptr + theta_base + 0).to(tl.float32)
    theta_01 = tl.load(theta_ptr + theta_base + 1).to(tl.float32)
    theta_02 = tl.load(theta_ptr + theta_base + 2).to(tl.float32)
    theta_10 = tl.load(theta_ptr + theta_base + 3).to(tl.float32)
    theta_11 = tl.load(theta_ptr + theta_base + 4).to(tl.float32)
    theta_12 = tl.load(theta_ptr + theta_base + 5).to(tl.float32)

    pair_mask = W - 1
    out_dtype = grid_ptr.dtype.element_ty
    lane = tl.arange(0, BLOCK)

    for c in tl.static_range(CHUNKS):
        flat2 = (pid * CHUNKS + c) * BLOCK + lane
        if MASK:
            in_range = flat2 < HW2
        # Element j of the flat grid is x of sample j // 2 when j is even and y
        # of the same sample when j is odd.
        pair = flat2 >> 1
        is_y = (flat2 & 1) == 1
        norm_x = (pair & pair_mask).to(tl.float32) * STEP_X - 1.0
        norm_y = (pair >> LOG_W).to(tl.float32) * STEP_Y - 1.0
        grid_x = theta_00 * norm_x + theta_01 * norm_y + theta_02
        grid_y = theta_10 * norm_x + theta_11 * norm_y + theta_12
        value = tl.where(is_y, grid_y, grid_x).to(out_dtype)
        offsets = n * HW2 + flat2
        if MASK:
            tl.store(grid_ptr + offsets, value, mask=in_range)
        else:
            tl.store(grid_ptr + offsets, value)


def _rows_per_program(H):
    """Grid rows written by one program: enough rows to amortize the scalar
    theta loads, few enough programs lost on small grids."""
    return max(1, min(MAX_ROWS, triton.next_power_of_2(H) // 8))


def _vec_plan(hw2, numel, row_elems, itemsize):
    """Tile plan for ``_vec_flat_kernel``, or ``None`` when it cannot be used.

    Returns ``(num_programs, block, chunks, planes, accum)``.  The plan keeps
    roughly ``VEC_CHUNKS_PER_PROGRAM`` chunks of ``block`` elements per program
    and caps ``block`` at ``VEC_BLOCK_MAX``; work per program follows the
    measured element budget for the output item size, and only a 4-byte grid
    that is already megabytes wide is allowed to fold two planes into one
    program (that was the fastest point for the 16x256x256 float32 grid).
    """
    if row_elems > VEC_BLOCK_MAX:
        return None

    elements_per_program = VEC_ELEMENTS_2B if itemsize <= 2 else VEC_ELEMENTS_4B
    per_program = min(hw2, elements_per_program)
    planes = 1
    # A wide 4-byte plane that leaves its element budget half used doubles up:
    # two planes per program measured 11.5us against 13.8us for one plane per
    # program on the 16x256x256 float32 grid.  Two-byte grids prefer the
    # smaller program, so this only applies above 2 bytes.
    if (
        itemsize > 2
        and hw2 >= 65536
        and per_program == hw2
        and 2 * hw2 <= elements_per_program
        and numel % (2 * hw2) == 0
    ):
        planes = 2
        per_program = 2 * hw2

    block = min(
        VEC_BLOCK_MAX, max(VEC_BLOCK_MIN, per_program // VEC_CHUNKS_PER_PROGRAM)
    )
    block = min(block, per_program // planes, hw2)
    block = max(block, row_elems)
    # Both are powers of two, so "block is a multiple of a row" holds.
    if block % row_elems:
        return None
    chunks = (per_program // planes) // block
    if chunks < 1 or hw2 % block or numel % per_program:
        return None
    return numel // per_program, block, chunks, planes, per_program < VEC_ACCUM_LIMIT


def _cudnn_affine_grid_generator_impl(theta, N, C, H, W, out=None):
    assert theta.shape == (N, 2, 3), f"theta must be shape (N, 2, 3), got {theta.shape}"

    out_shape = (N, H, W, 2)
    if out is None:
        out = torch.empty(out_shape, dtype=theta.dtype, device=theta.device)
    else:
        # ATen's out variant validates dtype/device and resizes shape
        # mismatches, so mirror that instead of writing past a small buffer.
        if out.device != theta.device:
            raise RuntimeError(
                f"Expected out tensor to have device {theta.device}, "
                f"but got {out.device} instead"
            )
        if out.dtype != theta.dtype:
            raise RuntimeError(
                f"Expected out tensor to have dtype {theta.dtype}, "
                f"but got {out.dtype} instead"
            )
        if tuple(out.shape) != out_shape:
            out.resize_(out_shape)

    if N * H * W * 2 == 0:
        return out

    # GCU has no FP64 unit: the compiler cannot legalize float64 arithmetic here
    # (`triton_gcu.elementwise_fusion_region` fails to lower, and even a plain fp64
    # copy trips a backend compiler assert), so a float64 `theta` runs the same
    # float32 kernels on a float32 workspace and the finished grid is cast back
    # into the caller's float64 buffer. The output dtype contract is preserved;
    # the values carry float32 intermediate precision (~1e-7 relative).
    grid_dtype = torch.float32 if theta.dtype == torch.float64 else theta.dtype
    grid_theta = theta.to(torch.float32) if theta.dtype == torch.float64 else theta
    if not grid_theta.is_contiguous():
        grid_theta = grid_theta.contiguous()
    grid_out = out
    if grid_dtype != out.dtype:
        grid_out = torch.empty(out_shape, dtype=grid_dtype, device=out.device)

    _launch_grid(grid_theta, N, H, W, grid_out)

    if grid_out is not out:
        out.copy_(grid_out)
    return out


def _launch_grid(theta, N, H, W, out):
    """Launch the best write path for one validated (theta, out) pair."""
    block_w = min(MAX_BLOCK_W, triton.next_power_of_2(W))
    num_col_blocks = triton.cdiv(W, block_w)
    rows = _rows_per_program(H)
    num_row_chunks = triton.cdiv(H, rows)
    batch_on_y = N <= MAX_GRID_Y

    hw2 = H * W * 2
    pow2_w = W == triton.next_power_of_2(W)
    pow2_h = H == triton.next_power_of_2(H)
    # align_corners=True steps (the size-1 denominator clamp keeps a degenerate
    # axis at its only sample, index 0 -> coordinate -1).
    step_x = 2.0 / max(W - 1, 1)
    step_y = 2.0 / max(H - 1, 1)
    if pow2_w and pow2_h and out.is_contiguous():
        plan = _vec_plan(hw2, N * hw2, 2 * W, out.element_size())
        if plan is not None:
            num_programs, block, chunks, planes, accum = plan
            # Rows advanced by one chunk of BLOCK elements.
            row_step = (block // (2 * W)) * step_y
            with torch_device_fn.device(theta.device):
                _vec_flat_kernel[(num_programs,)](
                    out,
                    theta,
                    W,
                    hw2,
                    hw2.bit_length() - 1,
                    step_x,
                    step_y,
                    row_step,
                    BLOCK=block,
                    CHUNKS=chunks,
                    PLANES=planes,
                    LOG_2W=(2 * W).bit_length() - 1,
                    ACCUM=accum,
                )
            return out

    # Power-of-two widths let the flat kernel split h/w with shifts, and a
    # contiguous grid lets it store straight into the interleaved output.
    use_flat = pow2_w and out.is_contiguous()
    if use_flat:
        block = min(FLAT_BLOCK, triton.next_power_of_2(hw2))
        # Keep about FLAT_BLOCK * FLAT_CHUNKS elements per program, but never
        # iterate more than there is work.
        elements_per_program = min(block * FLAT_CHUNKS, triton.next_power_of_2(hw2))
        chunks = max(1, elements_per_program // block)
        num_chunks = triton.cdiv(hw2, elements_per_program)
        grid = (num_chunks, N) if batch_on_y else (num_chunks * N,)
        with torch_device_fn.device(theta.device):
            cudnn_affine_grid_generator_flat_kernel[grid](
                out,
                theta,
                H,
                W,
                hw2,
                step_x,
                step_y,
                LOG_W=W.bit_length() - 1,
                BLOCK=block,
                CHUNKS=chunks,
                MASK=(hw2 % elements_per_program != 0),
                BATCH_ON_Y=batch_on_y,
                NUM_CHUNKS=num_chunks,
            )
        return out

    program_count = num_row_chunks * num_col_blocks
    grid = (program_count, N) if batch_on_y else (program_count * N,)

    with torch_device_fn.device(theta.device):
        cudnn_affine_grid_generator_kernel[grid](
            out,
            theta,
            H,
            W,
            *out.stride(),
            num_col_blocks,
            num_row_chunks,
            step_x,
            step_y,
            BLOCK_W=block_w,
            ROWS=rows,
            MASKED_W=(block_w != W),
            MASKED_H=(H % rows != 0),
            BATCH_ON_Y=batch_on_y,
        )

    return out


def cudnn_affine_grid_generator(theta, N, C, H, W):
    logger.debug("GEMS_ENFLAMECUDNN_AFFINE_GRID_GENERATOR")
    return _cudnn_affine_grid_generator_impl(theta, N, C, H, W)


def cudnn_affine_grid_generator_out(theta, N, C, H, W, *, out):
    logger.debug("GEMS_ENFLAMECUDNN_AFFINE_GRID_GENERATOR_OUT")
    if out is None:
        return _cudnn_affine_grid_generator_impl(theta, N, C, H, W)
    return _cudnn_affine_grid_generator_impl(theta, N, C, H, W, out=out)
